namespace tom {struct PanelTestAccess {static void setup(Panel&p){product::require(p.runtime_.finish(5000),"inline-fixture-runtime-stop");p.open({});p.bound_=true;p.commandPending_=false;p.notice_.clear();p.canvasRevision_=0;p.view_={};p.view_.ready=p.view_.configured=p.view_.editable=true;p.view_.thread=product::newId();p.view_.request=product::newId();p.view_.turn=product::newId();p.view_.nextWriting=true;p.view_.active=true;p.view_.context={{"version",1},{"scope","general"},{"excerpt",""}};p.view_.providerId="openai";p.view_.providerLabel="OpenAI";p.view_.model="gpt-5.4-mini";p.view_.maxOutputTokens=800;p.view_.answer="Memory and grief ";p.canvas_.restore({},false,false);p.paint();p.mark(true);p.canvas_.enable(true);}static void pump(Panel&p,std::chrono::steady_clock::time_point now=std::chrono::steady_clock::now()){p.syncReply();p.reply_.tick(false,now);p.paint();p.mark();p.addDamage(p.reply_.damage());}static void text(Panel&p,QString text,bool complete){p.view_.answer=std::move(text);p.view_.answerComplete=complete;p.view_.active=!complete;}static void automatic(Panel&p,QString text,bool complete){p.view_.request=product::newId();p.view_.autoReply=true;p.view_.purpose="auto-answer";p.view_.answerImageModel="gpt-image-2.5-flare";p.view_.answer=std::move(text);p.view_.answerComplete=complete;p.view_.active=!complete;}static void pending(Panel&p){p.pendingVisualConsent_=true;p.pendingVisualPrevious_=p.view_.request;}static bool live(const Panel&p){return p.liveImageRequest_==p.view_.request&&!p.pendingVisualConsent_;}static ReplyInk& reply(Panel&p){return p.reply_;}static const ib::tom::Model& model(const Panel&p){return p.answerModel_;}static void accepted(Panel&p){auto stamp=p.presentationStamp();for(int y=0;y<2160;y+=540)p.presentationCovered({0,y,1620,std::min(2160,y+540)},stamp);}};}
namespace {unsigned checks{};void verify(bool ok,std::source_location at=std::source_location::current()){++checks;if(!ok)throw std::runtime_error("Inline Tom regression check "+std::to_string(checks)+" line "+std::to_string(at.line())+" column "+std::to_string(at.column()));}template<class F>void until(F f){const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(5);while(std::chrono::steady_clock::now()<end){if(f())return;std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("Inline Tom fixture wait");}bool tap(tom::Panel&p,int id){auto r=p.targets().rect(id);return !r.empty()&&p.finger((r.x0+r.x1)/2,(r.y0+r.y1)/2);}}
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir temporary;temporary.setAutoRemove(false);try{verify(argc>=2&&temporary.isValid()&&ib::text::load(std::filesystem::path(argv[1])/"assets/fonts"));const auto root=std::filesystem::path(temporary.path().toStdString());{tom::Panel panel({},root,false);tom::PanelTestAccess::setup(panel);tom::PanelTestAccess::accepted(panel);until([&]{tom::PanelTestAccess::pump(panel);return tom::PanelTestAccess::reply(panel).ready();});verify(panel.active()&&panel.writable()&&tom::PanelTestAccess::model(panel).inlineComposer);verify(panel.targets().rect(ib::tom::FollowUp).empty()&&panel.targets().rect(ib::tom::InkReply).empty()&&panel.targets().rect(ib::tom::InkIllustrated).empty());verify(!panel.targets().rect(ib::tom::Type).empty());verify(panel.takeSaveRequest().isEmpty()&&!std::filesystem::exists(root/"documents"));tom::PanelTestAccess::accepted(panel);verify(tom::PanelTestAccess::reply(panel).damage().empty());auto now=std::chrono::steady_clock::now()+std::chrono::seconds(1);for(unsigned i=0;i<12;++i){tom::PanelTestAccess::pump(panel,now+std::chrono::milliseconds(i*40));verify(!panel.takeReset()&&panel.takeSaveRequest().isEmpty());tom::PanelTestAccess::accepted(panel);}verify(tom::PanelTestAccess::reply(panel).playing());
 const QString sentence="This passage is primarily about memory and loss. ";const auto longer=((sentence.repeated(6))+"\n\n").repeated(4);tom::PanelTestAccess::text(panel,longer,true);until([&]{tom::PanelTestAccess::pump(panel);return tom::PanelTestAccess::reply(panel).complete();});verify(panel.takeSaveRequest().isEmpty()&&!std::filesystem::exists(root/"documents"));tom::PanelTestAccess::reply(panel).finishInstantly();verify(panel.pan(400,1100,400,850));auto scrolled=tom::PanelTestAccess::reply(panel).scroll();verify(scrolled>0);tom::PanelTestAccess::text(panel,longer+"Another point. ",true);until([&]{tom::PanelTestAccess::pump(panel);return tom::PanelTestAccess::reply(panel).complete();});verify(tom::PanelTestAccess::reply(panel).scroll()==scrolled);verify(!panel.pan(400,1100,700,1110));tom::PanelTestAccess::reply(panel).finishInstantly();tom::PanelTestAccess::pump(panel);const auto expected=tom::PanelTestAccess::reply(panel).strokes();verify(!expected.isEmpty()&&tap(panel,ib::tom::SaveNote));auto save=panel.takeSaveRequest();verify(save.value("ink").toObject().value("mode")=="prepared"&&save.value("ink").toObject().value("strokes").toArray()==expected);verify(panel.active()&&!std::filesystem::exists(root/"documents"));if(argc>=3){std::vector<std::uint32_t> pixels(1632*2160);panel.composite({pixels,1620,2160,1632},{0,0,1620,2160});QImage image(reinterpret_cast<const uchar*>(pixels.data()),1620,2160,1632*4,QImage::Format_ARGB32);verify(image.save(QString::fromLocal8Bit(argv[2])));}tom::PanelTestAccess::automatic(panel,R"({"response":"","visual":{"type":"bar_chart","title":"Supplied values","values":[{"label":"Jan","value":150},{"label":"Feb","value":210}]}})",true);until([&]{tom::PanelTestAccess::pump(panel);return tom::PanelTestAccess::reply(panel).complete();});verify(tom::PanelTestAccess::reply(panel).kind()=="chart"&&panel.takeSaveRequest().isEmpty());verify(tap(panel,ib::tom::SaveNote)&&panel.takeSaveRequest().value("ink").toObject().value("kind")=="chart");panel.setPresentation(true,1,true);tom::PanelTestAccess::automatic(panel,R"({"response":"","visual":{"type":"bar_chart","title":"Typed accessibility chart","values":[{"label":"Jan","value":150},{"label":"Feb","value":210}]}})",true);until([&]{tom::PanelTestAccess::pump(panel);return tom::PanelTestAccess::reply(panel).complete();});verify(panel.outputMode()==tom::OutputMode::Typed&&tom::PanelTestAccess::model(panel).nativeReply&&tom::PanelTestAccess::model(panel).answer.empty());tom::PanelTestAccess::reply(panel).finishInstantly();tom::PanelTestAccess::pump(panel);{std::vector<std::uint32_t> pixels(1632*2160);panel.composite({pixels,1620,2160,1632},tom::ReplyInk::Area);bool ink=false;auto background=panel.background();for(int y=tom::ReplyInk::Area.y0;y<tom::ReplyInk::Area.y1&&!ink;++y)for(int x=tom::ReplyInk::Area.x0;x<tom::ReplyInk::Area.x1;++x)if(pixels[std::size_t(y)*1632+x]!=background[std::size_t(y)*1632+x]){ink=true;break;}verify(ink);}auto chartStrokes=tom::PanelTestAccess::reply(panel).strokes();verify(!chartStrokes.isEmpty()&&panel.takeSaveRequest().isEmpty()&&!std::filesystem::exists(root/"documents"));verify(tap(panel,ib::tom::SaveNote));auto chartSave=panel.takeSaveRequest().value("ink").toObject();verify(chartSave.value("mode")=="prepared"&&chartSave.value("kind")=="chart"&&chartSave.value("strokes").toArray()==chartStrokes&&chartSave.value("request")==panel.view().request);tom::PanelTestAccess::automatic(panel,R"({"response":"","visual":{"type":"bar_chart","title":"Cancelable visual","values":[{"label":"A","value":2},{"label":"B","value":3}]}})",true);until([&]{tom::PanelTestAccess::pump(panel);return tom::PanelTestAccess::reply(panel).complete();});verify(tom::PanelTestAccess::model(panel).canStop&&tom::PanelTestAccess::model(panel).status=="Tom is drawing…");verify(tap(panel,ib::tom::Stop));tom::PanelTestAccess::pump(panel);verify(panel.active()&&panel.writable()&&!tom::PanelTestAccess::reply(panel).ready()&&tom::PanelTestAccess::model(panel).canRetry&&!tom::PanelTestAccess::model(panel).canSaveNote&&panel.takeSaveRequest().isEmpty());tom::PanelTestAccess::pending(panel);tom::PanelTestAccess::automatic(panel,R"({"response":"An ordinary typed answer.","visual":null})",true);tom::PanelTestAccess::pump(panel);verify(tom::PanelTestAccess::live(panel));verify(!tom::PanelTestAccess::model(panel).nativeReply&&tom::PanelTestAccess::model(panel).answer=="An ordinary typed answer."&&!tom::PanelTestAccess::reply(panel).ready()&&tom::PanelTestAccess::reply(panel).strokes().isEmpty());verify(tap(panel,ib::tom::SaveNote));auto typedSave=panel.takeSaveRequest();verify(!typedSave.contains("ink")&&typedSave.value("answer")=="An ordinary typed answer.");tom::PanelTestAccess::automatic(panel,"{\"response\":\"",false);tom::PanelTestAccess::pump(panel);verify(!tom::PanelTestAccess::reply(panel).ready()&&tom::PanelTestAccess::reply(panel).strokes().isEmpty());tom::PanelTestAccess::automatic(panel,R"({"response":"pretend image","visual":{"type":"artwork","prompt":"Bird","detailed":false,"labels":[],"arrows":[]}})",true);tom::PanelTestAccess::pump(panel);verify(!panel.notice().isEmpty()&&tom::PanelTestAccess::reply(panel).strokes().isEmpty()&&panel.takeSaveRequest().isEmpty());verify(panel.finish(5000));}verify(temporary.remove());std::printf("TOM_INLINE_PANEL_PASS checks=%u native_response=true composer_continuous=true no_WriteAgain=true no_manual_visual_trigger=true no_automatic_Note=true Save_explicit_exact=true pan_detaches_follow=true stream_damage_regional=true automatic_chart=true invalid_visual_no_fabrication=true stale_preview_cleared=true typed_visual_native=true typed_visual_Save_exact=true typed_text_no_native=true typed_Save_no_transport_JSON=true regional_ack_retires=true provider_calls=0 physical=NOT_RUN\n",checks);return 0;}catch(const std::exception&e){std::fprintf(stderr,"TOM_INLINE_PANEL_FAIL %s fixture=%s\n",e.what(),temporary.path().toLocal8Bit().constData());return 1;}}
